def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    MOD = 1_000_000_007
    if n == 0:
        return 1
    if not banned:
        return pow(len(alphabet), n, MOD)

    k = len(alphabet)
    char_index = {c: i for i, c in enumerate(alphabet)}
    transitions = [[-1] * k]
    failure = [0]
    forbidden = [False]

    for word in banned:
        state = 0
        for c in word:
            i = char_index[c]
            if transitions[state][i] == -1:
                transitions[state][i] = len(transitions)
                transitions.append([-1] * k)
                failure.append(0)
                forbidden.append(False)
            state = transitions[state][i]
        forbidden[state] = True

    queue = deque()
    for i in range(k):
        child = transitions[0][i]
        if child == -1:
            transitions[0][i] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        fallback = failure[state]
        forbidden[state] |= forbidden[fallback]

        for i in range(k):
            child = transitions[state][i]
            if child == -1:
                transitions[state][i] = transitions[fallback][i]
            else:
                failure[child] = transitions[fallback][i]
                queue.append(child)

    safe = [s for s in range(len(transitions)) if not forbidden[s]]
    index = {state: i for i, state in enumerate(safe)}
    size = len(safe)
    matrix = [[0] * size for _ in range(size)]

    for state in safe:
        row = matrix[index[state]]
        for destination in transitions[state]:
            if not forbidden[destination]:
                row[index[destination]] += 1

    def multiply(a, b):
        columns = list(zip(*b))
        return [
            [
                sum(x * y for x, y in zip(row, column)) % MOD
                for column in columns
            ]
            for row in a
        ]

    vector = [[0] * size]
    vector[0][index[0]] = 1

    while n:
        if n & 1:
            vector = multiply(vector, matrix)
        n >>= 1
        if n:
            matrix = multiply(matrix, matrix)

    return sum(vector[0]) % MOD
